			this.callbacks = {
				updateCopilotState: BX.type.isFunction(config.updateCopilotState) ? config.updateCopilotState : BX.DoNothing,
				onClose: BX.type.isFunction(config.onClose) ? config.onClose : BX.DoNothing
			};
