			this.viewPort.setCallback(call_mapping.ViewEvent.onToggleSubscribe, this._onCallToggleSubscribeHandler);
			this.viewPort.setCallback(call_mapping.ViewEvent.onUserClick, this._onCallUserClickHandler);
			this.viewPort.setCallback(call_mapping.ViewEvent.onPiPClose, this._onPipCloseHandler);
			this.viewPort.setCallback(call_mapping.ViewEvent.onCommonRecordMenu, this.#onCommonRecordMenuHandler);
